insert into public.reference_material_aliases (alias_id, material_id, market_code, language_code, alias_text, alias_key, alias_kind, exact_identity, confidence, active)
select alias_id, material_id, market_code, language_code, alias_text, public.normalize_reference_material_alias(alias_text), alias_kind, exact_identity, confidence, true
from _gcm_aliases
on conflict (material_id, market_code, language_code, alias_key) do update set
  alias_text = excluded.alias_text, alias_kind = excluded.alias_kind, exact_identity = excluded.exact_identity, confidence = excluded.confidence, active = true;
commit;
